<?php

namespace App\Policies;

use App\Models\Enquiry;
use App\Models\User;

/**
 * Hand-written (not generated by Shield): customers may only touch their own enquiries;
 * staff need the matching permission (Admins pass every check via Shield's gate).
 */
class EnquiryPolicy
{
    public function viewAny(User $user): bool
    {
        return $user->isCustomer() || $user->can('ViewAny:Enquiry');
    }

    public function view(User $user, Enquiry $enquiry): bool
    {
        return $this->owns($user, $enquiry) || ($user->isStaff() && $user->can('View:Enquiry'));
    }

    public function create(User $user): bool
    {
        return ($user->isCustomer() && $user->customer !== null) || ($user->isStaff() && $user->can('Create:Enquiry'));
    }

    /** Customers edit only their drafts; staff with permission can edit any time. */
    public function update(User $user, Enquiry $enquiry): bool
    {
        if ($this->owns($user, $enquiry)) {
            return $enquiry->isEditableByCustomer();
        }

        return $user->isStaff() && $user->can('Update:Enquiry');
    }

    public function message(User $user, Enquiry $enquiry): bool
    {
        return $enquiry->status->isOpen()
            && ($this->owns($user, $enquiry) || ($user->isStaff() && $user->can('Update:Enquiry')));
    }

    public function cancel(User $user, Enquiry $enquiry): bool
    {
        return $enquiry->status->isCancellable()
            && ($this->owns($user, $enquiry) || ($user->isStaff() && $user->can('Update:Enquiry')));
    }

    public function delete(User $user, Enquiry $enquiry): bool
    {
        return $user->isStaff() && $user->can('Delete:Enquiry');
    }

    public function deleteAny(User $user): bool
    {
        return $user->isStaff() && $user->can('DeleteAny:Enquiry');
    }

    public function restore(User $user, Enquiry $enquiry): bool
    {
        return $user->isStaff() && $user->can('Restore:Enquiry');
    }

    public function restoreAny(User $user): bool
    {
        return $user->isStaff() && $user->can('RestoreAny:Enquiry');
    }

    private function owns(User $user, Enquiry $enquiry): bool
    {
        return $user->isCustomer()
            && $user->customer !== null
            && $enquiry->customer_id === $user->customer->id;
    }
}
